package com.vms.vendorcontractmanagement.service; import com.vms.vendorcontractmanagement.config.*; import com.vms.vendorcontractmanagement.dto.AuthDtos.*; import com.vms.vendorcontractmanagement.entity.*; import com.vms.vendorcontractmanagement.exception.*; import com.vms.vendorcontractmanagement.repository.*; import lombok.*; import org.springframework.http.*; import org.springframework.security.crypto.password.*; import org.springframework.stereotype.*;
@Service @RequiredArgsConstructor public class AuthService {final UserRepository users;final PasswordEncoder encoder;final JwtService jwt; public AuthResponse login(LoginRequest r){User u=users.findByEmail(r.email()).filter(x->x.getActive()&&encoder.matches(r.password(),x.getPasswordHash())).orElseThrow(()->new ApiException(HttpStatus.UNAUTHORIZED,"Invalid credentials"));return new AuthResponse(jwt.generate(u.getEmail(),u.getRole().getName()),"Bearer",u.getFullName(),u.getRole().getName());} }
